```c
// bk7258_yuv_buf.c ISR
static int bk7258_yuv_buf_isr(int irq, FAR void *context, FAR void *arg)
{
  uint32_t status = getreg32(YUV_BUF_INT_STATUS);
  putreg32(status, YUV_BUF_INT_STATUS);
  g_isr_count++;
  g_last_status = status;
  if ((status & YUV_BUF_INT_VSYNC_NEGE) != 0) { g_vsync_count++; }
  if ((status & YUV_BUF_INT_ERRORS) != 0) { g_err_count++; g_err_status |= status & YUV_BUF_INT_ERRORS; }
  if ((status & YUV_BUF_INT_YUV_ARV) != 0) {
    g_frame_count++;
    if (g_frame_cb != NULL) { g_frame_cb(g_frame_cb_arg); }
  }
  return 0;
}

// bk7258_camera_imgdata.c
static void bk7258_camera_watchdog_arm(FAR struct bk7258_camera_imgdata_s *priv)
{
  priv->frames_at_arm = priv->frames_done;
  wd_start(&priv->watchdog, MSEC2TICK(BK7258_CAMERA_WATCHDOG_MS),
           bk7258_camera_watchdog_expiry, (wdparm_t)priv);
}

static void bk7258_camera_frame_done(FAR void *arg)
{
  FAR struct bk7258_camera_imgdata_s *priv = arg;
  struct timeval ts;
  if (!priv->capturing || priv->frame_buf == NULL) { return; }
  priv->frames_done++;
  if (priv->capture_cb != NULL) {
    bk7258_camera_now(&ts);
    priv->capture_cb(0, priv->frame_buf_size, &ts, priv->capture_cb_arg);
  }
  if (priv->capturing) { bk7258_camera_watchdog_arm(priv); }
}

static void bk7258_camera_watchdog_expiry(wdparm_t arg)
{
  FAR struct bk7258_camera_imgdata_s *priv = (FAR struct bk7258_camera_imgdata_s *)arg;
  struct timeval ts;
  if (!priv->capturing) { return; }
  if (priv->frames_done == priv->frames_at_arm) {
    priv->timeouts++;
    if (priv->capture_cb != NULL) {
      bk7258_camera_now(&ts);
      priv->capture_cb(EIO, 0, &ts, priv->capture_cb_arg);
    }
  }
  if (priv->capturing) { bk7258_camera_watchdog_arm(priv); }
}

static int bk7258_camera_imgdata_stop_capture(FAR struct imgdata_s *data)
{
  FAR struct bk7258_camera_imgdata_s *priv = (FAR struct bk7258_camera_imgdata_s *)data;
  priv->capturing = false;
  wd_cancel(&priv->watchdog);
  bk7258_yuv_buf_stop();
  ...
}

// bk7258_gc2145_i2c_bitbang.c
static bool bk7258_i2c1_send_byte(uint8_t data)
{
  int bit; bool acked;
  for (bit = 7; bit >= 0; bit--) { bk7258_i2c1_write_bit((data & (1u << bit)) != 0); }
  bk7258_i2c1_sda_release();
  bk7258_i2c1_delay();
  bk7258_i2c1_scl_high();
  bk7258_i2c1_delay();
  acked = !bk7258_i2c1_sda_read();
  bk7258_i2c1_scl_low();
  bk7258_i2c1_delay();
  bk7258_i2c1_sda_high();
  return acked;
}

static void bk7258_i2c1_start(void)
{
  bk7258_i2c1_sda_high();
  bk7258_i2c1_delay();
  bk7258_i2c1_scl_high();
  bk7258_i2c1_delay();
  bk7258_i2c1_sda_low();
  bk7258_i2c1_delay();
  bk7258_i2c1_scl_low();
  bk7258_i2c1_delay();
}

bool bk7258_i2c1_read_reg(uint8_t i2c_addr, uint8_t reg, FAR uint8_t *value)
{
  if (value == NULL) { return false; }
  bk7258_i2c1_start();
  if (!bk7258_i2c1_send_byte((uint8_t)(i2c_addr << 1))) { bk7258_i2c1_stop(); return false; }
  if (!bk7258_i2c1_send_byte(reg)) { bk7258_i2c1_stop(); return false; }
  bk7258_i2c1_start();
  if (!bk7258_i2c1_send_byte((uint8_t)((i2c_addr << 1) | 1u))) { bk7258_i2c1_stop(); return false; }
  *value = bk7258_i2c1_recv_byte(false);
  bk7258_i2c1_stop();
  return true;
}

// bk7258_camera_imgsensor.c power_off called from failed init() paths
static void bk7258_gc2145_power_off(void)
{
  uint32_t reg;
  bk7258_gpio_output(DVP_RESET_PIN, false);
  reg = getreg32(BK7258_SYS_REG_0X0D);
  reg &= ~BK7258_SYS_CIS_AUXS_CKEN;
  putreg32(reg, BK7258_SYS_REG_0X0D);
  bk7258_gpio_output(DVP_POWER_PIN, false);
}

